// OPS-12 - Preparar Consulta: valida token y normaliza filtros, paginado y tema.
const TOKEN = 'QLreport-m4x7-2026';
const q = $json.query || {};
if (String(q.k || '') !== TOKEN) {
  return [{ json: {
    authorized: false,
    error: 'forbidden',
    message: 'Acceso no autorizado: falta o es invalido el parametro k',
  } }];
}

const clean = (v, max = 160) => String(v ?? '').trim().slice(0, max);

const lead = clean(q.lead, 40);
const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(lead);

const SELECTORS = ['quicklink_id', 'telefono', 'nombre', 'chatwoot_conv'];
const selectorRaw = clean(q.selector, 30).toLowerCase();
const selector = SELECTORS.includes(selectorRaw) ? selectorRaw : '';
const valor = clean(q.valor, 160);
const digits = valor.replace(/\D/g, '');

const marcaRaw = clean(q.marca, 12).toUpperCase();
const marca = ['KIA', 'HYUNDAI'].includes(marcaRaw) ? marcaRaw : '';

const ESTADOS = ['PENDIENTE', 'REZAGADO', 'EN_GESTION', 'GESTION_PERDIDA', 'CONFIRMADA_AI'];
const estadoRaw = clean(q.estado, 30).toUpperCase();
const estado = ESTADOS.includes(estadoRaw) ? estadoRaw : '';

const dateOk = (v) => (/^\d{4}-\d{2}-\d{2}$/.test(v) && !Number.isNaN(new Date(v + 'T00:00:00Z').getTime()) ? v : '');
const desde = dateOk(clean(q.desde, 10));
const hasta = dateOk(clean(q.hasta, 10));

const sizeRaw = Number.parseInt(clean(q.page_size || q.limite, 5), 10);
const page_size = Number.isInteger(sizeRaw) && sizeRaw > 0 ? Math.min(Math.max(sizeRaw, 25), 250) : 100;
const pageRaw = Number.parseInt(clean(q.page, 7), 10);
const page = Number.isInteger(pageRaw) && pageRaw > 0 ? Math.min(pageRaw, 10000) : 1;
const offset = (page - 1) * page_size;

const themeRaw = clean(q.theme, 10).toLowerCase();
const theme = ['light', 'dark'].includes(themeRaw) ? themeRaw : '';
const exportRaw = clean(q.export, 8).toLowerCase();
const downloadRaw = clean(q.download, 30).toLowerCase();
const download = ['leads_xlsx', 'leads_pdf', 'leads_csv', 'leads_json'].includes(downloadRaw) ? downloadRaw : '';
const export_all = ['1', 'true', 'yes', 'all'].includes(exportRaw) || !!download;

let error_msg = '';
if (selector && !valor) error_msg = 'Indica un valor para el criterio seleccionado.';
else if (selector === 'telefono' && digits.length < 7) error_msg = 'El telefono debe tener al menos 7 digitos.';
else if (selector === 'quicklink_id' && !/^\d{1,9}$/.test(valor)) error_msg = 'El QuickLink ID debe ser numerico.';
else if (selector === 'chatwoot_conv' && !/^\d{1,9}$/.test(valor)) error_msg = 'El ID de conversacion Chatwoot debe ser numerico.';
else if (desde && hasta && desde > hasta) error_msg = 'La fecha desde no puede ser posterior a la fecha hasta.';

const mode = isUuid ? 'report' : (error_msg ? 'form' : 'list');

return [{ json: {
  authorized: true,
  mode,
  k: TOKEN,
  lead_uuid: isUuid ? lead.toLowerCase() : '',
  selector,
  valor,
  digits,
  last9: digits.slice(-9),
  marca,
  marca_sel: marca || 'AMBAS',
  estado,
  desde,
  hasta,
  limite: page_size,
  page_size,
  page,
  offset,
  theme,
  export_all,
  download,
  error_msg,
} }];

// OPS-12 - Construir Pagina Reporte: UI read-only con dashboard, dark mode, paginado y exportaciones.
const cfg = (() => { try { return $('Preparar Consulta').first().json; } catch (e) { return $input.first().json || {}; } })();
let listRow = null;
try { listRow = $('Buscar Leads').first().json; } catch (e) { listRow = null; }
let report = null;
try { report = $('Consolidar Reporte').first().json; } catch (e) { report = null; }

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const dash = (v) => (v === null || v === undefined || v === '' ? '-' : String(v));
const num = (v) => Number(v || 0).toLocaleString('es-EC');
const pct = (a, b) => (Number(b || 0) > 0 ? Math.round((Number(a || 0) * 1000) / Number(b)) / 10 : 0);
const fmtDate = (v) => {
  if (!v) return '-';
  const d = typeof v === 'number' ? new Date(v * 1000) : new Date(v);
  if (Number.isNaN(d.getTime())) return esc(String(v));
  return d.toLocaleString('es-EC', { timeZone: 'America/Guayaquil', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
};
const fileStamp = () => new Date().toISOString().slice(0, 10);
const brandBadge = (b) => {
  const v = String(b || 'SIN_MARCA').toUpperCase();
  const cls = v === 'KIA' ? 'brand-kia' : v === 'HYUNDAI' ? 'brand-hyundai' : 'brand-other';
  return `<span class="brand ${cls}">${esc(v)}</span>`;
};
const stateBadge = (s) => {
  const v = String(s || 'SIN_ESTADO').toUpperCase();
  const cls = v.includes('PERDIDA') || v.includes('LOST') ? 'state-loss' : v.includes('CONFIRM') || v.includes('WON') || v.includes('GANADO') ? 'state-win' : v.includes('PEND') || v.includes('REZAG') ? 'state-warn' : 'state-work';
  return `<span class="state ${cls}">${esc(v)}</span>`;
};
const kv = (label, valueHtml) => `<div class="kv"><span>${esc(label)}</span><div>${valueHtml}</div></div>`;
const kvT = (label, value) => kv(label, `<strong>${esc(dash(value))}</strong>`);
const statCard = (label, value, hint, cls = '') => `<article class="stat ${cls}"><span>${esc(label)}</span><strong>${esc(num(value))}</strong><small>${esc(hint || '')}</small></article>`;
const arrayRows = (v) => Array.isArray(v) ? v : [];

const selfUrl = (extra = {}) => {
  const pairs = {
    k: cfg.k,
    selector: cfg.selector || '',
    valor: cfg.valor || '',
    marca: cfg.marca || '',
    estado: cfg.estado || '',
    desde: cfg.desde || '',
    hasta: cfg.hasta || '',
    page_size: cfg.page_size || cfg.limite || 100,
    page: cfg.page || 1,
    theme: cfg.theme || '',
  };
  Object.assign(pairs, extra || {});
  const qs = Object.entries(pairs)
    .filter(([k, v]) => v !== undefined && v !== null && v !== '')
    .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v)))
    .join('&');
  return '?' + qs;
};

const SELECTOR_OPTS = [
  ['', 'Sin criterio (dashboard general)'],
  ['quicklink_id', 'QuickLink ID'],
  ['telefono', 'Telefono'],
  ['nombre', 'Nombre cliente'],
  ['chatwoot_conv', 'Conversacion Chatwoot'],
];
const ESTADO_OPTS = ['', 'PENDIENTE', 'REZAGADO', 'EN_GESTION', 'GESTION_PERDIDA', 'CONFIRMADA_AI'];
const PAGE_SIZES = [25, 50, 100, 250];
const selOpts = (pairs, cur) => pairs.map(([v, l]) => `<option value="${esc(v)}"${v === cur ? ' selected' : ''}>${esc(l)}</option>`).join('');
const plainOpts = (arr, cur) => arr.map(v => `<option value="${esc(v)}"${v === cur ? ' selected' : ''}>${esc(v || 'Todos')}</option>`).join('');
const pageSizeOpts = PAGE_SIZES.map(v => `<option value="${v}"${Number(cfg.page_size || cfg.limite || 100) === v ? ' selected' : ''}>${v}</option>`).join('');

const exportColumns = [
  ['quicklink_id', 'QL ID', (l) => l.quicklink_id],
  ['id', 'Lead ID', (l) => l.id],
  ['nombre_cliente', 'Cliente', (l) => l.nombre_cliente],
  ['telefono_1', 'Telefono cliente', (l) => l.telefono_1],
  ['telefono_agente', 'Telefono agente', (l) => l.telefono_agente || l.telefono_1],
  ['marca', 'Marca', (l) => l.marca],
  ['modelo', 'Modelo', (l) => l.modelo],
  ['agencia', 'Agencia', (l) => l.agencia],
  ['ciudad', 'Ciudad', (l) => l.ciudad],
  ['estado_agente', 'Estado lead', (l) => l.estado_agente],
  ['estado_ql', 'Estado QL', (l) => l.estado_ql],
  ['estado_conv', 'Estado conversacion', (l) => l.estado_conv],
  ['chatwoot_conv_id', 'Chatwoot conv', (l) => l.chatwoot_conv_id],
  ['fecha_asignacion', 'Fecha asignacion', (l) => l.fecha_asignacion],
  ['created_at', 'Creado', (l) => l.created_at],
  ['sincronizado_at', 'Ultima sync', (l) => l.sincronizado_at],
  ['reportado_ql', 'Reportado QL', (l) => l.reportado_ql ? 'SI' : 'NO'],
];
const exportRowsFor = (rows) => arrayRows(rows).map((lead) => {
  const out = {};
  exportColumns.forEach((col) => { out[col[1]] = col[2](lead); });
  return out;
});
const csvEscape = (v) => '"' + String(v ?? '').replace(/\r?\n/g, ' ').replace(/"/g, '""') + '"';
const csvFromRows = (rows) => {
  const safeRows = rows.length ? rows : [{ info: 'Sin datos' }];
  const keys = Object.keys(safeRows[0] || { info: '' });
  return String.fromCharCode(65279) + [keys.join(';')].concat(safeRows.map((row) => keys.map((key) => csvEscape(row[key])).join(';'))).join(String.fromCharCode(10));
};
const xmlEsc = (v) => String(v ?? '')
  .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, ' ')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const sheetXml = (name, rows) => {
  const safeRows = rows.length ? rows : [{ info: 'Sin datos' }];
  const keys = Object.keys(safeRows[0] || { info: '' });
  const rowXml = (row) => '<Row>' + keys.map((key) => {
    const raw = row[key];
    const str = String(raw ?? '');
    const n = Number(str);
    const numeric = str !== '' && Number.isFinite(n) && str.trim() === String(n);
    return '<Cell><Data ss:Type="' + (numeric ? 'Number' : 'String') + '">' + xmlEsc(str) + '</Data></Cell>';
  }).join('') + '</Row>';
  const header = '<Row>' + keys.map((key) => '<Cell><Data ss:Type="String">' + xmlEsc(key) + '</Data></Cell>').join('') + '</Row>';
  return '<Worksheet ss:Name="' + xmlEsc(String(name || 'Sheet').slice(0, 31)) + '"><Table>' + header + safeRows.map(rowXml).join('') + '</Table></Worksheet>';
};
const buildExcelXml = (payload) => {
  const dash = payload.dashboard || {};
  const kpis = dash.kpis || {};
  const filters = payload.filters || {};
  const sheets = [
    ['Leads', exportRowsFor(payload.export_leads || [])],
    ['KPIs', Object.keys(kpis).map((key) => ({ metrica: key, valor: kpis[key] }))],
    ['Filtros', Object.keys(filters).map((key) => ({ filtro: key, valor: filters[key] || '' }))],
    ['Marca', arrayRows(dash.by_brand)],
    ['Estado', arrayRows(dash.by_state)],
    ['Conversacion', arrayRows(dash.by_conversation)],
    ['Antiguedad', arrayRows(dash.by_age)],
    ['Modelos', arrayRows(dash.top_models)],
    ['Agencias', arrayRows(dash.top_agencies)],
  ];
  return '<?xml version="1.0" encoding="UTF-8"?><?mso-application progid="Excel.Sheet"?>'
    + '<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">'
    + sheets.map((sheet) => sheetXml(sheet[0], sheet[1])).join('')
    + '</Workbook>';
};
const asciiClean = (v) => String(v ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^\x20-\x7e]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const pdfEsc = (v) => asciiClean(v).replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
const fixed = (v, width) => {
  const s = asciiClean(v);
  const clipped = s.length > width ? s.slice(0, Math.max(1, width - 1)) + '~' : s;
  return clipped.padEnd(width, ' ');
};
const buildLeadsPdf = (payload) => {
  const leads = arrayRows(payload.export_leads);
  const pagination = payload.pagination || {};
  const filters = payload.filters || {};
  const filtersText = Object.keys(filters).map((key) => key + '=' + (filters[key] || 'todos')).join(' | ');
  const cols = [
    ['QL', 8, (l) => l.quicklink_id],
    ['CLIENTE', 24, (l) => l.nombre_cliente],
    ['TEL AGENTE', 14, (l) => l.telefono_agente || l.telefono_1],
    ['MARCA', 8, (l) => l.marca],
    ['MODELO', 20, (l) => l.modelo],
    ['AGENCIA', 16, (l) => l.agencia],
    ['ESTADO', 16, (l) => l.estado_agente],
    ['ASIGNADO', 10, (l) => String(l.fecha_asignacion || l.created_at || '').slice(0, 10)],
  ];
  const header = cols.map((col) => fixed(col[0], col[1])).join(' ');
  const lines = leads.map((lead) => cols.map((col) => fixed(col[2](lead), col[1])).join(' '));
  const rowsPerPage = 42;
  const pageCount = Math.max(1, Math.ceil(lines.length / rowsPerPage));
  const text = (x, y, size, value) => 'BT /F1 ' + size + ' Tf ' + x + ' ' + y + ' Td (' + pdfEsc(value) + ') Tj ET\n';
  const objs = [null, '', '', '<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>'];
  const addObj = (body) => { objs.push(body); return objs.length - 1; };
  const pageIds = [];
  for (let page = 0; page < pageCount; page += 1) {
    const chunk = lines.slice(page * rowsPerPage, (page + 1) * rowsPerPage);
    let stream = '';
    stream += text(32, 562, 11, 'OPS-12 Lead Ops - Leads export');
    stream += text(32, 548, 7, 'Generado: ' + new Date().toISOString() + ' | Filtrados: ' + (pagination.total || leads.length) + ' | Exportados: ' + leads.length + (pagination.export_capped ? ' | LIMITADO' : ''));
    stream += text(32, 536, 7, 'Filtros: ' + fixed(filtersText || 'todos', 150));
    stream += text(32, 518, 6, header);
    stream += text(32, 508, 6, '-'.repeat(header.length));
    let y = 496;
    chunk.forEach((line) => { stream += text(32, y, 6, line); y -= 10; });
    stream += text(748, 24, 7, 'Pagina ' + (page + 1) + ' / ' + pageCount);
    const contentId = addObj('<< /Length ' + stream.length + ' >>\nstream\n' + stream + 'endstream');
    const pageId = addObj('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /Font << /F1 3 0 R >> >> /Contents ' + contentId + ' 0 R >>');
    pageIds.push(pageId);
  }
  objs[1] = '<< /Type /Catalog /Pages 2 0 R >>';
  objs[2] = '<< /Type /Pages /Kids [' + pageIds.map((id) => id + ' 0 R').join(' ') + '] /Count ' + pageIds.length + ' >>';
  let pdf = '%PDF-1.4\n% OPS12\n';
  const offsets = [0];
  for (let i = 1; i < objs.length; i += 1) {
    offsets[i] = pdf.length;
    pdf += i + ' 0 obj\n' + objs[i] + '\nendobj\n';
  }
  const xref = pdf.length;
  pdf += 'xref\n0 ' + objs.length + '\n0000000000 65535 f \n';
  for (let i = 1; i < objs.length; i += 1) pdf += String(offsets[i]).padStart(10, '0') + ' 00000 n \n';
  pdf += 'trailer\n<< /Size ' + objs.length + ' /Root 1 0 R >>\nstartxref\n' + xref + '\n%%EOF\n';
  return pdf;
};
const exportStamp = () => new Date().toISOString().slice(0, 10);
const safeFilename = (v) => (String(v || 'ops12-export').replace(/[^a-z0-9._-]+/gi, '-').replace(/^-+|-+$/g, '').slice(0, 140) || 'ops12-export');
const buildDirectExport = (payload) => {
  const action = payload && payload.download_action;
  if (!['leads_xlsx', 'leads_pdf', 'leads_csv', 'leads_json'].includes(action)) return null;
  const rows = exportRowsFor(payload.export_leads || []);
  const suffix = payload.pagination && payload.pagination.export_capped ? '-limitado' : '';
  const base = safeFilename('ops12-leads-' + exportStamp() + suffix);
  if (action === 'leads_csv') return { body: csvFromRows(rows), contentType: 'text/csv; charset=utf-8', filename: base + '.csv' };
  if (action === 'leads_json') return { body: JSON.stringify(payload, null, 2), contentType: 'application/json; charset=utf-8', filename: base + '.json' };
  if (action === 'leads_xlsx') return { body: buildExcelXml(payload), contentType: 'application/vnd.ms-excel; charset=utf-8', filename: base + '.xls' };
  if (action === 'leads_pdf') return { body: buildLeadsPdf(payload), contentType: 'application/pdf', filename: base + '.pdf' };
  return null;
};

const filterChips = (() => {
  const chips = [];
  if (cfg.selector) chips.push(['Criterio', SELECTOR_OPTS.find(([v]) => v === cfg.selector)?.[1] || cfg.selector]);
  if (cfg.valor) chips.push(['Valor', cfg.valor]);
  if (cfg.marca) chips.push(['Marca', cfg.marca]);
  if (cfg.estado) chips.push(['Estado', cfg.estado]);
  if (cfg.desde) chips.push(['Desde', cfg.desde]);
  if (cfg.hasta) chips.push(['Hasta', cfg.hasta]);
  return chips.length ? `<div class="chips">${chips.map(([a, b]) => `<span class="chip"><b>${esc(a)}</b>${esc(b)}</span>`).join('')}<a class="linkbtn ghost" href="?k=${esc(cfg.k)}">Limpiar</a></div>` : `<div class="chips"><span class="chip muted-chip">Vista general sin filtros</span></div>`;
})();

const formCard = `<section class="panel no-print">
  <div class="section-head"><div><p class="eyebrow">1 / Filtros</p><h2>Segmentacion</h2><p>Refina la base sin modificar datos.</p></div></div>
  <form method="GET" action="" id="searchform" onsubmit="return lockSearch(this)">
    <input type="hidden" name="k" value="${esc(cfg.k)}">
    <input type="hidden" name="theme" id="themeInput" value="${esc(cfg.theme || '')}">
    <input type="hidden" name="page" value="1">
    <div class="paramgrid">
      <label>Buscar por<select name="selector">${selOpts(SELECTOR_OPTS, cfg.selector)}</select></label>
      <label>Valor<input type="text" name="valor" value="${esc(cfg.valor || '')}" placeholder="ID, telefono, nombre" autocomplete="off"></label>
      <label>Marca<select name="marca">${plainOpts(['', 'KIA', 'HYUNDAI'], cfg.marca)}</select></label>
      <label>Estado lead<select name="estado">${plainOpts(ESTADO_OPTS, cfg.estado)}</select></label>
      <label>Desde<input type="date" name="desde" value="${esc(cfg.desde || '')}"></label>
      <label>Hasta<input type="date" name="hasta" value="${esc(cfg.hasta || '')}"></label>
      <label>Filas por pagina<select name="page_size">${pageSizeOpts}</select></label>
      <button class="primary" type="submit" id="searchbtn">Aplicar filtros</button>
    </div>
  </form>
  ${filterChips}
  ${cfg.error_msg ? `<div class="notice notice-warn"><strong>Revisa la busqueda</strong><span>${esc(cfg.error_msg)}</span></div>` : ''}
</section>`;

const barList = (title, rows, total, empty = 'Sin datos') => `<section class="panel mini-panel"><div class="section-head compact"><div><h3>${esc(title)}</h3></div></div>
  ${rows.length ? `<div class="bars">${rows.map(r => {
    const n = Number(r.count || 0);
    const w = Math.max(2, pct(n, total));
    return `<div class="barrow"><div><b>${esc(dash(r.label))}</b><span>${esc(num(n))} (${esc(pct(n, total))}%)</span></div><div class="bar"><i style="width:${w}%"></i></div></div>`;
  }).join('')}</div>` : `<p class="obs">${esc(empty)}</p>`}
</section>`;

let pageData = null;
let listHtml = '';
if (cfg.mode === 'list' && listRow) {
  const leads = arrayRows(listRow.leads);
  const exportLeads = arrayRows(listRow.export_leads);
  const dashboard = listRow.dashboard || {};
  const kpis = dashboard.kpis || {};
  const total = Number(listRow.total || 0);
  const pageSize = Number(listRow.page_size || cfg.page_size || cfg.limite || 100);
  const page = Number(listRow.page || cfg.page || 1);
  const offset = Number(listRow.offset || 0);
  const pageCount = Math.max(1, Math.ceil(total / Math.max(1, pageSize)));
  const first = total ? offset + 1 : 0;
  const last = Math.min(offset + leads.length, total);
  const exportLimit = Number(listRow.export_limit || 10000);
  const baseTotal = Number(listRow.base_total || total);
  const exportCapped = cfg.export_all === true && total > exportLeads.length;
  const rows = leads.map(l => `<tr>
    <td data-label="QL ID" class="mono idcell">${esc(dash(l.quicklink_id))}</td>
    <td data-label="Cliente" class="nom">${esc(dash(l.nombre_cliente))}</td>
    <td data-label="Telefono agente" class="mono">${esc(dash(l.telefono_agente || l.telefono_1))}</td>
    <td data-label="Marca">${brandBadge(l.marca)}</td>
    <td data-label="Modelo" class="modelcell">${esc(dash(l.modelo))}</td>
    <td data-label="Agencia">${esc(dash(l.agencia))}</td>
    <td data-label="Estado lead">${stateBadge(l.estado_agente)}</td>
    <td data-label="Estado conv.">${l.estado_conv ? stateBadge(l.estado_conv) : '-'}</td>
    <td data-label="Asignado">${fmtDate(l.fecha_asignacion || l.created_at)}</td>
    <td data-label="Reporte"><a class="linkbtn" href="${esc(selfUrl({ lead: l.id }))}">Ver reporte</a></td>
  </tr>`).join('\n');

  const pagination = `<nav class="pager no-print" aria-label="Paginacion">
    <div><b>${esc(num(first))}-${esc(num(last))}</b> de <b>${esc(num(total))}</b> leads · pagina ${esc(num(page))} de ${esc(num(pageCount))}</div>
    <div class="pager-actions">
      ${page > 1 ? `<a class="linkbtn" href="${esc(selfUrl({ page: 1 }))}">Primera</a><a class="linkbtn" href="${esc(selfUrl({ page: page - 1 }))}">Anterior</a>` : `<span class="linkbtn disabled">Primera</span><span class="linkbtn disabled">Anterior</span>`}
      ${page < pageCount ? `<a class="linkbtn" href="${esc(selfUrl({ page: page + 1 }))}">Siguiente</a><a class="linkbtn" href="${esc(selfUrl({ page: pageCount }))}">Ultima</a>` : `<span class="linkbtn disabled">Siguiente</span><span class="linkbtn disabled">Ultima</span>`}
    </div>
  </nav>`;

  pageData = {
    type: 'list',
    generated_at: new Date().toISOString(),
    filters: { selector: cfg.selector, valor: cfg.valor, marca: cfg.marca, estado: cfg.estado, desde: cfg.desde, hasta: cfg.hasta },
    pagination: { base_total: baseTotal, total, page, page_size: pageSize, page_count: pageCount, first, last, export_limit: exportLimit, export_capped: exportCapped },
    dashboard,
    page_leads: leads,
    export_ready: cfg.export_all === true,
    download_action: cfg.download || '',
    export_leads: cfg.export_all === true ? exportLeads : [],
  };

  const directExport = cfg.export_all === true ? buildDirectExport(pageData) : null;
  if (directExport) {
    return [{ json: {
      mode: cfg.mode,
      download: cfg.download,
      response_body: directExport.body,
      response_content_type: directExport.contentType,
      response_disposition: 'attachment; filename="' + directExport.filename.replace(/"/g, '') + '"',
      page_html: directExport.body,
    } }];
  }

  const dashboardHtml = `<section class="dashboard" id="dashboard-export">
    <div class="summary hero-summary">
      ${statCard('Filtrados', kpis.total || total, `de ${num(baseTotal)} en base`)}
      ${statCard('Pendientes', kpis.pendientes, `${pct(kpis.pendientes, total)}% del filtro`, 'accent-warn')}
      ${statCard('En gestion', kpis.en_gestion, `${pct(kpis.en_gestion, total)}% del filtro`, 'accent-info')}
      ${statCard('Confirmadas AI', kpis.confirmadas_ai, `${pct(kpis.confirmadas_ai, total)}% del total`, 'accent-ok')}
      ${statCard('Con conversacion', kpis.con_conversacion, `${pct(kpis.con_conversacion, total)}% vinculados`, 'accent-hyundai')}
      ${statCard('Sin conversacion', kpis.sin_conversacion, 'requieren revision de cobertura', 'accent-kia')}
      ${statCard('Pendientes 30d+', kpis.pendientes_30d, 'antiguedad critica', 'accent-danger')}
      ${statCard('No reportados QL', kpis.no_reportados_ql, 'pendiente de cierre/reporting', 'accent-purple')}
    </div>
    <div class="grid2">
      ${barList('Distribucion por estado', arrayRows(dashboard.by_state), total)}
      ${barList('Distribucion por marca', arrayRows(dashboard.by_brand), total)}
    </div>
    <div class="grid3">
      ${barList('Conversacion CRIS', arrayRows(dashboard.by_conversation), total)}
      ${barList('Antiguedad del lead', arrayRows(dashboard.by_age), total)}
      <section class="panel mini-panel"><div class="section-head compact"><div><h3>Sincronizacion</h3></div></div>
        <div class="kvgrid single">
          ${kv('Ultima sync', `<strong>${fmtDate(kpis.ultima_sync)}</strong>`)}
          ${kv('Mas antiguo', `<strong>${fmtDate(kpis.mas_antiguo)}</strong>`)}
          ${kv('Mas reciente', `<strong>${fmtDate(kpis.mas_reciente)}</strong>`)}
          ${kv('Telefono invalido', `<strong>${esc(num(kpis.telefono_invalido || 0))}</strong>`)}
        </div>
      </section>
    </div>
    <div class="grid2">
      ${barList('Top modelos', arrayRows(dashboard.top_models), total)}
      ${barList('Top agencias', arrayRows(dashboard.top_agencies), total)}
    </div>
  </section>`;

  const exportWarn = exportCapped ? `<div class="notice notice-warn"><strong>Exportacion limitada</strong><span>El set filtrado tiene ${esc(num(total))} leads; el navegador recibio ${esc(num(exportLeads.length))} por seguridad. Sube el limite SQL si necesitas mas de ${esc(num(exportLimit))}.</span></div>` : '';

  listHtml = `<section class="panel no-print">
      <div class="section-head"><div><p class="eyebrow">2 / Resumen</p><h2>Estado operativo</h2><p>Indicadores sobre el filtro actual. La exportacion completa se prepara bajo demanda.</p></div>
      <div class="actions"><button type="button" onclick="exportDashboardPdf()">PDF resumen</button><button type="button" onclick="exportDashboardXlsx()">Excel resumen</button><a class="linkbtn" href="${esc(selfUrl({ export: 1, download: 'leads_xlsx' }))}">Excel leads</a><a class="linkbtn" href="${esc(selfUrl({ export: 1, download: 'leads_csv' }))}">CSV leads</a><a class="linkbtn" href="${esc(selfUrl({ export: 1, download: 'leads_pdf' }))}">PDF leads</a></div></div>
      ${exportWarn}
    </section>
    ${dashboardHtml}
    <section class="panel table-card" id="leads-table-section">
      <div class="section-head"><div><p class="eyebrow">3 / Leads</p><h2>Listado operativo</h2><p>Pagina actual servida desde base. Usa exportacion para descargar el set completo filtrado.</p></div></div>
      ${pagination}
      ${leads.length ? `<div class="tablewrap"><table>
        <thead><tr><th>QL ID</th><th>Cliente</th><th>Telefono agente</th><th>Marca</th><th>Modelo</th><th>Agencia</th><th>Estado lead</th><th>Estado conv.</th><th>Asignado</th><th></th></tr></thead>
        <tbody>${rows}</tbody>
      </table></div>` : `<div class="empty"><h3>Sin resultados</h3><p>No hay leads para los criterios indicados. Ajusta filtros y vuelve a buscar.</p></div>`}
      ${pagination}
    </section>`;
}

const SOURCE_LABEL = { ok: 'Disponible', partial: 'Parcial', unavailable: 'No disponible', empty: 'Sin datos' };
const sourceChip = (name, status) => {
  const st = SOURCE_LABEL[status] ? status : 'empty';
  return `<span class="src src-${st}" title="${esc(name)}: ${esc(SOURCE_LABEL[st])}">${esc(name)} · ${esc(SOURCE_LABEL[st])}</span>`;
};

let reportHtml = '';
if (cfg.mode === 'report') {
  if (!report || !report.lead) {
    reportHtml = `<section class="panel empty"><h2>Lead no encontrado</h2><p>El identificador indicado no existe en la base.</p><p><a class="linkbtn" href="?k=${esc(cfg.k)}">Nueva busqueda</a></p></section>`;
  } else {
    const r = report;
    const lead = r.lead || {};
    const conv = r.conv || null;
    const cal = r.calificacion || null;
    const plan = r.plan || null;
    const handoff = r.handoff || null;
    const cw = r.chatwoot || { status: 'unavailable' };
    const ob = r.outbound || {};
    const tl = arrayRows(r.timeline);
    const warnings = arrayRows(r.warnings);
    const src = r.sources || {};
    const dispatches = arrayRows(ob.dispatches);
    const buttons = arrayRows(ob.botones);

    pageData = {
      type: 'report',
      generated_at: new Date().toISOString(),
      report: {
        lead,
        conversation: conv || {},
        calificacion: cal || {},
        plan: plan || {},
        handoff: handoff || {},
        chatwoot: cw || {},
        outbound: { dispatches, botones: buttons },
        timeline: tl,
        warnings,
        sources: src,
      },
    };

    const chips = `<div class="srcbar">
      ${sourceChip('Base de datos', src.db)}
      ${sourceChip('QuickLink espejo', src.quicklink_mirror)}
      ${sourceChip('Chatwoot', src.chatwoot)}
      ${sourceChip('WhatsApp Meta almacenado', src.meta_stored)}
    </div>`;

    const resumenCard = `<section class="panel">
      <div class="section-head"><div><p class="eyebrow">2 / Lead</p><h2>${esc(dash(lead.nombre_cliente))}</h2><p>Datos de leads_quicklink sincronizados desde QuickLink.</p></div><div>${brandBadge(lead.marca)}</div></div>
      <div class="kvgrid">
        ${kvT('QuickLink ID', lead.quicklink_id)}
        ${kv('Lead ID', `<small class="mono">${esc(dash(lead.id))}</small>`)}
        ${kv('Telefono cliente', `<strong class="mono">${esc(dash(lead.telefono_1))}</strong>${lead.telefono_2 ? ` <small class="mono">· ${esc(lead.telefono_2)}</small>` : ''}`)}
        ${kv('Telefono agente', `<strong class="mono">${esc(dash(lead.telefono_agente))}</strong>`)}
        ${kvT('Modelo', lead.modelo)}
        ${kvT('Chasis', lead.chasis)}
        ${kvT('Agencia', lead.agencia)}
        ${kvT('Vendedor QL', lead.nombre_vendedor_ql)}
        ${kv('Estado QuickLink', stateBadge(lead.estado_ql))}
        ${kv('Estado agente', stateBadge(lead.estado_agente))}
        ${kv('Fecha venta', `<strong>${fmtDate(lead.fecha_venta)}</strong>`)}
        ${kv('Ultima sync', `<strong>${fmtDate(lead.ultima_sync_at)}</strong>`)}
        ${kv('Reportado a QuickLink', `<strong>${lead.reportado_ql ? 'Si · ' + fmtDate(lead.reportado_ql_at) : 'No'}</strong>`)}
      </div>
      ${lead.observacion_ql ? `<p class="obs"><b>Observacion QuickLink:</b> ${esc(lead.observacion_ql)}</p>` : ''}
    </section>`;

    const comercialCard = `<section class="panel">
      <div class="section-head"><div><p class="eyebrow">3 / Gestion</p><h2>Estado comercial</h2><p>Conversacion CRIS, calificacion y resultado.</p></div></div>
      ${conv ? `<div class="kvgrid">
        ${kv('Estado CRIS', `${stateBadge(conv.estado)}${conv.estado_anterior ? ` <small>antes: ${esc(conv.estado_anterior)}</small>` : ''}`)}
        ${kv('Desde', `<strong>${fmtDate(conv.estado_updated_at)}</strong>`)}
        ${kvT('Intentos', conv.intentos_realizados)}
        ${kv('Ultima respuesta', `<strong>${fmtDate(conv.ultima_respuesta_at)}</strong>`)}
        ${kv('Proximo contacto', `<strong>${fmtDate(conv.proximo_intento_at || conv.proxima_accion_at)}</strong>`)}
        ${kvT('Senal compra', conv.senal_compra)}
        ${kvT('Plan interes', conv.plan_interes)}
        ${plan ? kv('Plan catalogo', `<strong>${esc(dash(plan.nombre_plan))}</strong> <small>· ${esc(dash(plan.meses))} meses · $${esc(dash(plan.precio_usd))}</small>`) : ''}
        ${kvT('Mensajes env/rec', `${dash(conv.total_mensajes_enviados)} / ${dash(conv.total_mensajes_recibidos)}`)}
        ${conv.razon_perdida ? kv('Razon perdida', `<strong class="danger-text">${esc(conv.razon_perdida)}</strong>`) : ''}
        ${r.convs_total > 1 ? kv('Conversaciones', `<strong>${esc(r.convs_total)}</strong> <small>multiple</small>`) : ''}
      </div>` : `<p class="obs">Sin conversacion CRIS vinculada a este lead.</p>`}
      ${cal ? `<div class="subblock"><h3>Calificacion consultiva</h3><div class="kvgrid">
        ${kvT('Score', cal.score_calificacion)}${kvT('Necesidad', cal.necesidad_clasificada)}${kvT('Urgencia', cal.urgencia)}${kvT('Presupuesto', cal.presupuesto)}${kvT('Vehiculos', cal.cantidad_vehiculos)}${kvT('Plan sugerido', cal.plan_sugerido)}${kv('Completa', `<strong>${cal.calificacion_completa ? 'Si' : 'No'} · ${dash(cal.preguntas_respondidas)} preguntas</strong>`)}
      </div></div>` : ''}
      ${handoff ? `<div class="subblock"><h3>Handoff humano</h3><div class="kvgrid">${kvT('Asesor', handoff.asesor_nombre)}${kvT('Razon', handoff.razon_transferencia)}${kv('Fecha', `<strong>${fmtDate(handoff.created_at)}</strong>`)}${kv('Notificado Chatwoot', `<strong>${handoff.notificado_chatwoot ? 'Si' : 'No'}</strong>`)}${kv('Reportado QL', `<strong>${handoff.reportado_ql ? 'Si' : 'No'}${handoff.estado_reporte_ql ? ' · ' + esc(handoff.estado_reporte_ql) : ''}</strong>`)}</div>${handoff.resumen_conversacion ? `<p class="obs"><b>Resumen:</b> ${esc(String(handoff.resumen_conversacion).slice(0, 400))}</p>` : ''}</div>` : ''}
    </section>`;

    let cwBody = '';
    if (cw.status === 'unavailable') cwBody = `<div class="notice notice-warn"><strong>Chatwoot</strong><span>Informacion temporalmente no disponible. El resto del reporte no se afecta.</span></div>`;
    else if (cw.status === 'empty') cwBody = `<p class="obs">Sin conversacion Chatwoot vinculada.</p>`;
    else {
      const c = cw.conversation || {};
      const notes = arrayRows(cw.private_notes).slice(-5);
      cwBody = `<div class="kvgrid">
        ${kvT('Conversation ID', cw.conv_id)}${kv('Estado', stateBadge(c.status))}${kvT('Inbox', c.inbox && c.inbox.name ? `${c.inbox.name} (#${c.inbox_id ?? c.inbox.id})` : c.inbox_id)}${kvT('Assignee ID', c.assignee_id)}${kv('Labels', (Array.isArray(c.labels) && c.labels.length) ? c.labels.map(l => `<span class="pill">${esc(l)}</span>`).join(' ') : '-')}${kv('Ultima actividad', `<strong>${fmtDate(c.last_activity_at)}</strong>`)}${kvT('Mensajes', cw.messages_count)}${kvT('Notas privadas', cw.private_count)}${kvT('Contacto', cw.contact_id)}
      </div>${notes.length ? `<div class="subblock"><h3>Ultimas notas privadas</h3>${notes.map(n => `<p class="note"><small>${fmtDate(n.created_at)}</small> ${esc(String(n.content || '').slice(0, 260))}</p>`).join('')}</div>` : ''}`;
    }
    const chatwootCard = `<section class="panel"><div class="section-head"><div><p class="eyebrow">4 / Chatwoot</p><h2>CRM y notas</h2><p>Consulta read-only via probe interno.</p></div></div>${cwBody}</section>`;

    const dispatchError = (d) => {
      if (d.error_code || d.error_message) return [d.error_code, d.error_message].filter(Boolean).join(' ');
      const msgs = arrayRows(d.messages);
      const errs = msgs.filter(m => m.error_code || m.error_message).map(m => [m.error_code, m.error_message].filter(Boolean).join(' '));
      if (errs.length) return errs.join(' · ');
      if (d.delivery_status === 'failed') return msgs.length ? 'sin codigo (' + msgs.map(m => m.status || '?').join(', ') + ')' : 'sin mensajes registrados';
      return '';
    };
    const obRows = dispatches.map(d => `<tr><td data-label="Fecha">${fmtDate(d.created_at)}</td><td data-label="Origen">${esc(dash(d.source))}</td><td data-label="Intake">${stateBadge(d.intake_status)}</td><td data-label="Entrega">${stateBadge(d.delivery_status)}</td><td data-label="Enviado">${fmtDate(d.sent_at)}</td><td data-label="Entregado">${fmtDate(d.delivered_at)}</td><td data-label="Leido">${fmtDate(d.read_at)}</td><td data-label="Error" class="mono">${dispatchError(d) ? `<span class="danger-text">${esc(dispatchError(d))}</span>` : '-'}</td></tr>`).join('');
    const msgRows = dispatches.flatMap(d => arrayRows(d.messages).map(m => `<p class="note"><small>${fmtDate(d.created_at)}</small> <span class="pill">${esc(dash(m.role))}</span> ${esc(dash(m.status))}${m.error_code || m.error_message ? ` <span class="danger-text">${esc([m.error_code, m.error_message].filter(Boolean).join(' '))}</span>` : ''} <small class="mono">${esc(dash(m.meta_message_id))}</small></p>`));
    const whatsappCard = `<section class="panel"><div class="section-head"><div><p class="eyebrow">5 / WhatsApp</p><h2>Entrega e interacciones</h2><p>Estados almacenados por el sistema.</p></div></div>
      ${dispatches.length ? `<div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Origen</th><th>Intake</th><th>Entrega</th><th>Enviado</th><th>Entregado</th><th>Leido</th><th>Error</th></tr></thead><tbody>${obRows}</tbody></table></div>` : `<p class="obs">Sin envios outbound registrados para este lead.</p>`}
      ${msgRows.length ? `<div class="subblock"><h3>Mensajes Meta</h3>${msgRows.join('')}</div>` : ''}
      ${buttons.length ? `<div class="subblock"><h3>Botones</h3>${buttons.slice(0, 8).map(b => `<p class="note"><small>${fmtDate(b.created_at)}</small> <span class="pill">${esc(dash(b.button_title || b.button_key))}</span> ${esc(dash(b.status))}${b.reason ? ` <small>· ${esc(b.reason)}</small>` : ''}</p>`).join('')}</div>` : ''}
      ${conv && conv.ultima_respuesta_at ? `<p class="hint">Ventana conversacional estimada 24h: <b>${r.ventana_abierta ? 'ABIERTA' : 'CERRADA'}</b>.</p>` : ''}
    </section>`;

    const tlRows = tl.map(ev => `<div class="tl-item"><div class="tl-when">${fmtDate(ev.fecha)}</div><div class="tl-dot tl-${esc(ev.origen || 'db')}"></div><div class="tl-body"><div><span class="pill">${esc(dash(ev.tipo))}</span> <small class="tl-src">${esc(dash(ev.origen))}</small></div>${ev.descripcion ? `<p>${esc(String(ev.descripcion).slice(0, 240))}</p>` : ''}${(ev.estado_anterior || ev.estado_posterior) ? `<small>${esc(dash(ev.estado_anterior))} -> ${esc(dash(ev.estado_posterior))}</small>` : ''}</div></div>`).join('\n');
    const timelineCard = `<section class="panel"><div class="section-head"><div><p class="eyebrow">6 / Timeline</p><h2>Eventos consolidados</h2><p>Mas recientes primero, maximo 200.</p></div></div>${tl.length ? `<div class="tl">${tlRows}</div>` : `<p class="obs">Sin eventos registrados.</p>`}</section>`;
    const warnCard = `<section class="panel"><div class="section-head"><div><p class="eyebrow">7 / Auditoria</p><h2>Alertas e inconsistencias</h2><p>Reglas verificables sobre datos consolidados.</p></div></div>${warnings.length ? warnings.map(w => `<div class="notice notice-danger"><strong>${esc(w.regla)}</strong><span>${esc(w.evidencia)}</span></div>`).join('') : `<div class="notice notice-ok"><strong>Sin alertas</strong><span>No se detectaron inconsistencias con las reglas activas.</span></div>`}</section>`;

    reportHtml = `<p class="backlink no-print"><a class="linkbtn" href="${esc(selfUrl({ lead: null }))}">Volver a resultados</a></p>
      <section class="panel no-print"><div class="section-head"><div><p class="eyebrow">Reporte individual</p><h2>Lead #${esc(dash(lead.quicklink_id))}</h2><p>Consolidado QuickLink, CRIS, Chatwoot y WhatsApp.</p></div><div class="actions"><button type="button" onclick="exportReportPdf()">Reporte PDF</button><button type="button" onclick="exportReportXlsx()">Reporte Excel</button></div></div>${chips}${warnings.length ? `<div class="notice notice-danger"><strong>${warnings.length} alerta(s)</strong><span>Revisa la seccion de inconsistencias.</span></div>` : ''}</section>
      <div id="report-export">${resumenCard}<div class="grid2">${comercialCard}${chatwootCard}</div><div class="grid2">${whatsappCard}${timelineCard}</div>${warnCard}</div>`;
  }
}

const emptyStateHtml = (cfg.mode === 'form' && !cfg.error_msg)
  ? `<section class="panel empty"><h2>Consulta un lead</h2><p>Usa los criterios para generar el dashboard interno o un reporte consolidado.</p></section>`
  : '';

const dataScript = pageData ? `<script id="ops12-data" type="application/json">${JSON.stringify(pageData).replace(/</g, '\\u003c')}</script>` : '';
const libs = '';

const html = `<!DOCTYPE html>
<html lang="es" data-theme="${esc(cfg.theme || 'light')}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<title>Reporte de Leads CRIS</title>
<script>(function(){var t='${esc(cfg.theme || '')}';try{var m=location.search.match(/[?&]theme=(dark|light)(?:&|$)/);if(m)t=m[1];}catch(e){}try{if(!t)t=localStorage.getItem('ops12-theme')||'';}catch(e){}document.documentElement.setAttribute('data-theme',t||'light');})();</script>
<style>
  :root { color-scheme:light; --bg:#f5f6f8; --surface:#ffffff; --surface-2:#f9fafb; --ink:#111827; --muted:#5f6775; --soft:#8a93a3; --line:#d9dee7; --line-2:#edf0f4; --accent:#1f4d7a; --accent-2:#174265; --kia:#9f1d2b; --hyundai:#0b5d8e; --warn:#9a6700; --danger:#a33a2b; --ok:#166534; --focus:rgba(31,77,122,.18); }
  html[data-theme="dark"] { color-scheme:dark; --bg:#0b0d12; --surface:#11151d; --surface-2:#151a23; --ink:#e8edf3; --muted:#a5adba; --soft:#7f8998; --line:#29313d; --line-2:#1f2630; --accent:#7aa7d6; --accent-2:#9fc1e3; --focus:rgba(122,167,214,.22); }
  * { box-sizing:border-box; }
  body { margin:0; padding:18px 18px 40px; font-family:Inter, 'IBM Plex Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; color:var(--ink); background:var(--bg); font-size:14px; }
  .wrap { max-width:1320px; margin:0 auto; }
