  .hero h1 { margin:0; font-size:28px; letter-spacing:-.04em; line-height:1; font-weight:850; }
  .hero p { margin:7px 0 0; color:var(--muted); font-size:13px; max-width:760px; }
  .hero-actions, .actions, .pager-actions, .head-tools { display:flex; gap:8px; flex-wrap:wrap; align-items:center; justify-content:flex-end; }
  .panel { background:var(--surface); border:1px solid var(--line); border-radius:12px; padding:16px; margin-bottom:14px; box-shadow:none; }
  .mini-panel { margin-bottom:0; }
  .section-head { display:flex; align-items:flex-start; justify-content:space-between; gap:16px; margin-bottom:14px; }
  .section-head.compact { margin-bottom:10px; }
  .section-head h2, .section-head h3 { margin:0 0 4px; letter-spacing:-.025em; line-height:1.1; }
  .section-head h2 { font-size:19px; } .section-head h3 { font-size:14px; }
  .section-head p { margin:0; color:var(--muted); font-size:12px; }
  .eyebrow { margin:0 0 6px !important; color:var(--soft) !important; font-size:10px !important; font-weight:850; letter-spacing:.14em; text-transform:uppercase; }
  .paramgrid { display:grid; grid-template-columns:1.1fr 1.4fr .9fr 1fr .9fr .9fr .8fr auto; gap:10px; align-items:end; }
