  input, select { width:100%; min-height:38px; border:1px solid var(--line); border-radius:8px; background:var(--surface-2); color:var(--ink); font:inherit; font-size:13px; padding:8px 10px; outline:none; transition:border-color .15s, box-shadow .15s, background .15s; }
