  button, .linkbtn { min-height:34px; border:1px solid var(--line); border-radius:8px; background:var(--surface); color:var(--ink); font:inherit; font-size:12px; font-weight:800; padding:7px 11px; cursor:pointer; text-decoration:none; display:inline-flex; align-items:center; justify-content:center; transition:background .12s, border-color .12s, color .12s; }
  button:hover:not(:disabled), .linkbtn:hover { background:var(--surface-2); border-color:var(--soft); }
  .primary { min-height:38px; background:var(--ink); color:var(--bg); border-color:var(--ink); }
  html[data-theme="dark"] .primary { color:#0b0d12; background:#e8edf3; border-color:#e8edf3; }
