  .disabled { opacity:.38; pointer-events:none; }
  .chips { display:flex; gap:7px; flex-wrap:wrap; margin-top:12px; align-items:center; }
  .chip { display:inline-flex; gap:6px; align-items:center; min-height:26px; padding:5px 9px; border:1px solid var(--line); border-radius:999px; background:var(--surface-2); color:var(--muted); font-size:11px; }
  .chip b { color:var(--ink); }
