async function exportDashboardPdf(){try{var d=data();if(d.type!=='list')return;notify('Preparando PDF de dashboard...');var dash=d.dashboard||{};var k=dash.kpis||{};var doc=await pdfDoc('landscape');doc.setFontSize(16);doc.text('OPS-12 - Dashboard de Leads',36,36);doc.setFontSize(9);doc.text('Generado: '+new Date().toLocaleString('es-EC'),36,54);doc.text('Filtros: '+filtersText(d.filters),36,68,{maxWidth:760});doc.autoTable({head:[['Metrica','Valor']],body:Object.keys(k).map(function(key){return [key,safe(k[key])];}),startY:86,styles:{fontSize:8,cellPadding:4},headStyles:{fillColor:[36,38,45]}});var y=doc.lastAutoTable.finalY+16;var groups=[['Por estado',dash.by_state||[]],['Por marca',dash.by_brand||[]],['Conversacion',dash.by_conversation||[]],['Antiguedad',dash.by_age||[]],['Top modelos',dash.top_models||[]],['Top agencias',dash.top_agencies||[]]];groups.forEach(function(g){doc.autoTable({head:[[g[0],'Leads']],body:(g[1]||[]).map(function(r){return [safe(r.label),safe(r.count)];}),startY:y,styles:{fontSize:8,cellPadding:3},headStyles:{fillColor:[49,91,168]}});y=doc.lastAutoTable.finalY+12;if(y>500){doc.addPage();y=36;}});addFooter(doc);doc.save('ops12-dashboard-'+slug()+'.pdf');notify('Descarga PDF iniciada: dashboard.');}catch(e){fail('No se pudo generar PDF de dashboard.',e);}}
