return [{ json: { page_html: html, mode: cfg.mode, response_content_type: 'text/html; charset=utf-8', response_disposition: 'inline' } }];

// OPS-12 · Consolidar Reporte — une BD + Chatwoot + Meta almacenado, aplica reglas de alertas
const detail = $('Cargar Detalle Lead').first().json || {};
let tlRow = {};
try { tlRow = $('Cargar Timeline').first().json || {}; } catch (e) { tlRow = {}; }
const probeOut = $input.first().json || {};

const lead = detail.lead || null;
const conv = detail.conv || null;
const dispatches = Array.isArray(detail.dispatches) ? detail.dispatches : [];
const botones = Array.isArray(detail.botones) ? detail.botones : [];
const queue = Array.isArray(detail.queue) ? detail.queue : [];
const fupsPend = Array.isArray(detail.followups_pendientes) ? detail.followups_pendientes : [];

const rawEvents = Array.isArray(tlRow.events) ? tlRow.events : [];
const timeline = rawEvents.map((row) => {
  const d = row.datos || {};
  if (row.clase === 'EVENTO') {
    let desc = d.contenido || '';
    if (!desc && d.payload && typeof d.payload === 'object') desc = JSON.stringify(d.payload).slice(0, 200);
    if (!desc && d.datos_evento && typeof d.datos_evento === 'object') desc = JSON.stringify(d.datos_evento).slice(0, 200);
    return {
      fecha: row.fecha,
      origen: row.origen,
      tipo: d.tipo_evento || d.tipo || 'EVENTO',
      descripcion: String(desc || '').slice(0, 240),
      estado_anterior: d.estado_anterior || d.estado_origen || null,
      estado_posterior: d.estado_nuevo || d.estado_destino || null,
    };
  }
  return {
    fecha: row.fecha,
    origen: row.origen,
    tipo: d.tipo || 'EVENTO',
    descripcion: d.descripcion || '',
    estado_anterior: d.estado_anterior || null,
    estado_posterior: d.estado_posterior || null,
  };
});

let chatwoot = { status: 'unavailable' };
const probeConvId = detail.probe_conv_id || null;
if (probeOut && probeOut.ok === true) {
  const convs = Array.isArray(probeOut.conversations) ? probeOut.conversations : [];
  const searches = Array.isArray(probeOut.searches) ? probeOut.searches : [];
  if (probeConvId && convs.length) {
    const c = convs[0];
    if (c.conversation_status === 200 && c.conversation) {
      chatwoot = {
        status: 'ok',
        conv_id: c.id,
        conversation: c.conversation,
        contact_id: c.conversation.contact_id || null,
        messages_count: c.messages_count,
        private_count: c.private_count,
        public_count: c.public_count,
        private_notes: c.private_notes || [],
      };
    } else {
      chatwoot = { status: 'partial', conv_id: c.id, error: c.conversation_error || ('HTTP ' + c.conversation_status) };
    }
  } else if (searches.length) {
    const s = searches[0];
    if (s.count > 0) chatwoot = { status: 'partial', contact_id: s.results[0].id, contact_name: s.results[0].name, note: 'Contacto encontrado por telefono; sin conversacion vinculada en BD.' };
    else chatwoot = { status: 'empty' };
  } else {
    chatwoot = { status: 'empty' };
  }
} else if (!probeConvId && !detail.probe_phone) {
  chatwoot = { status: 'empty' };
}

let ventana_abierta = false;
if (conv && conv.ultima_respuesta_at) {
  const last = new Date(conv.ultima_respuesta_at).getTime();
  ventana_abierta = Number.isFinite(last) && (Date.now() - last) < 24 * 3600 * 1000;
}

const warnings = [];
const warn = (regla, evidencia) => warnings.push({ regla, evidencia });
const TERMINAL = ['WON', 'LOST', 'NOT_CONTACTABLE', 'DISCARDED']; // enum canonico V80, sin alias muertos
const estadoConv = conv ? String(conv.estado || '').toUpperCase() : '';
const estadoAgente = lead ? String(lead.estado_agente || '').toUpperCase() : '';

if (conv && (TERMINAL.includes(estadoConv) || estadoConv === 'HANDOFF_HUMAN') && fupsPend.length > 0) {
  warn('Follow-up pendiente en estado terminal',
    `Estado ${estadoConv} con ${fupsPend.length} follow-up(s) en PENDING/CLAIMED/PROCESSING.`);
}
if (conv && conv.plan_interes && !['PLAN_SELECTED', 'HANDOFF_HUMAN', 'WON'].includes(estadoConv)) {
  const hasTransition = timeline.some(ev => String(ev.estado_posterior || '').toUpperCase() === 'PLAN_SELECTED');
  if (!hasTransition) warn('Plan de interes sin estado PLAN_SELECTED',
    `plan_interes="${conv.plan_interes}" con estado ${estadoConv} y sin transicion registrada a PLAN_SELECTED.`);
}
if (detail.handoff && detail.handoff.created_at) {
  const hAt = new Date(detail.handoff.created_at).getTime();
  const post = dispatches.filter(d => new Date(d.created_at).getTime() > hAt);
  if (post.length) warn('Outbound posterior al handoff',
    `${post.length} dispatch(es) creados despues de la transferencia a humano (${detail.handoff.created_at}).`);
}
if ((detail.convs_total || 0) > 1) {
  warn('Multiples conversaciones para el lead', `Existen ${detail.convs_total} conversaciones vinculadas en BD.`);
}
// El error de Meta se guarda en outbound_dispatch_messages; refresh_outbound_dispatch_status
// marca el dispatch como failed sin propagar error_code (V129), por eso se busca en ambos niveles.
const dispatchErr = (d) => {
  if (d.error_code || d.error_message) return [d.error_code, d.error_message].filter(Boolean).join(' ');
  const msgs = Array.isArray(d.messages) ? d.messages : [];
  const errs = [...new Set(msgs.filter(m => m.error_code || m.error_message)
    .map(m => [m.error_code, m.error_message].filter(Boolean).join(' ')))];
  return errs.join(' | ') || 'sin codigo registrado';
};
const failed = dispatches.filter(d => d.failed_at);
if (failed.length) {
  warn('Envios WhatsApp fallidos',
    failed.map(d => `${d.failed_at}: ${dispatchErr(d)}`).join(' - ').slice(0, 260));
}
if (estadoAgente === 'EN_GESTION' && (detail.eventos_count || 0) === 0) {
  warn('Lead en gestion sin eventos', 'estado_agente=EN_GESTION pero eventos_conversacion no registra actividad.');
}
if (conv) {
  // Direccion conversacion -> lead: la FSM cerro pero el lead no lo refleja.
  if (estadoConv === 'WON' && estadoAgente !== 'CONFIRMADA_AI') {
    warn('Conversacion ganada sin registrar en el lead',
      `Conversacion en WON pero lead estado_agente=${estadoAgente}.`);
  }
  if (['LOST', 'NOT_CONTACTABLE', 'DISCARDED'].includes(estadoConv) && estadoAgente !== 'GESTION_PERDIDA') {
    warn('Conversacion perdida sin registrar en el lead',
      `Conversacion en ${estadoConv} pero lead estado_agente=${estadoAgente}.`);
  }
  // Direccion lead -> conversacion: la venta/perdida se registro pero la conversacion sigue abierta.
  // Patron real en prod: lead CONFIRMADA_AI con conversacion estacionada en HANDOFF_HUMAN
  // (falta la transicion advisor_closed_won; ningun flujo la ejecuta hoy).
  if (estadoAgente === 'CONFIRMADA_AI' && !TERMINAL.includes(estadoConv)) {
    warn('Venta registrada sin cerrar la conversacion',
      `Lead en CONFIRMADA_AI pero la conversacion sigue en ${estadoConv}; falta la transicion advisor_closed_won.`);
  }
  if (estadoAgente === 'GESTION_PERDIDA' && !TERMINAL.includes(estadoConv)) {
    warn('Perdida registrada sin cerrar la conversacion',
      `Lead en GESTION_PERDIDA pero la conversacion sigue en ${estadoConv}.`);
  }
}
const qFailed = queue.filter(q => q.status === 'FAILED');
if (qFailed.length) {
  warn('Reporte a QuickLink fallido', qFailed.map(q => `${q.tipo_evento} (${q.intentos} intentos)`).join(' - '));
}
if (TERMINAL.includes(estadoConv) && queue.some(q => q.status === 'PENDING')) {
  warn('Reporte a QuickLink pendiente en estado terminal', `Estado ${estadoConv} con eventos PENDING en sync_queue.`);
}
if (chatwoot.status === 'ok' && chatwoot.conversation && chatwoot.conversation.status === 'resolved'
    && conv && !TERMINAL.includes(estadoConv) && estadoConv !== 'HANDOFF_HUMAN') {
  warn('Chatwoot resuelta con estado CRIS activo', `Chatwoot status=resolved pero conversacion CRIS en ${estadoConv}.`);
}
if (lead) {
  const brandMismatch = dispatches.filter(d => d.marca && lead.marca && String(d.marca).toUpperCase() !== String(lead.marca).toUpperCase());
  if (brandMismatch.length) {
    warn('Dispatch con marca distinta al lead', `${brandMismatch.length} envio(s) con marca ${brandMismatch[0].marca} para lead ${lead.marca}.`);
  }
}

const sources = {
  db: lead ? 'ok' : 'empty',
  quicklink_mirror: lead && lead.ultima_sync_at ? 'ok' : (lead ? 'partial' : 'empty'),
  chatwoot: chatwoot.status === 'ok' ? 'ok' : chatwoot.status === 'partial' ? 'partial' : chatwoot.status === 'empty' ? 'empty' : 'unavailable',
  meta_stored: dispatches.length || botones.length ? 'ok' : 'empty',
};

return [{ json: {
  lead,
  conv,
  convs_total: detail.convs_total || 0,
  calificacion: detail.calificacion || null,
  plan: detail.plan || null,
  handoff: detail.handoff || null,
  followups_pendientes: fupsPend,
  followups_recientes: detail.followups_recientes || [],
  outbound: { dispatches, botones, failed_count: detail.dispatches_failed || 0 },
  queue,
  ultima_sync: detail.ultima_sync || null,
  contexto: detail.contexto || null,
  eventos_count: detail.eventos_count || 0,
  chatwoot,
  timeline,
  warnings,
  sources,
  ventana_abierta,
} }];
